@charset "UTF-8";

:root{
  --ink:#070a0b;
  --ink-2:#0d1213;
  --steel:#1a2224;
  --line:rgba(255,255,255,.12);
  --line-strong:rgba(255,255,255,.22);
  --text:#e9eef0;
  --dim:#8b9a9e;
  --accent:#ff6a1a;
  --accent-2:#ffb03a;
  --green:#7ee787;
  --red:#ff4d3d;
  --cyan:#7ce7ff;
  --font:"Barlow Condensed","Arial Narrow","Helvetica Neue",Arial,sans-serif;
  --mono:"SF Mono","Roboto Mono",Menlo,Consolas,monospace;
}

*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
html,body{width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--text);font-family:var(--font)}
body{position:fixed;inset:0;touch-action:none;user-select:none;-webkit-user-select:none}
canvas#game{position:fixed;inset:0;width:100%;height:100%;display:block;outline:none}

.hidden{display:none !important}
.dim{color:#67767a}

/* ---------- loading ---------- */
#loading{
  position:fixed;inset:0;z-index:200;background:radial-gradient(circle at 50% 55%,#121a1b,#050707 70%);
  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:18px;
  font-size:13px;letter-spacing:.32em;color:#92a3a7;transition:opacity .5s;
}
#loading.gone{opacity:0;pointer-events:none}
.load-mark{width:54px;height:54px;border:2px solid rgba(255,106,26,.2);border-top-color:var(--accent);border-radius:50%;animation:spin 1s linear infinite;position:relative}
.load-mark:after{content:"";position:absolute;inset:8px;border:1px solid rgba(255,255,255,.15);border-radius:50%}
@keyframes spin{to{transform:rotate(360deg)}}

/* ---------- HUD base ---------- */
#hud{position:fixed;inset:0;z-index:20;pointer-events:none;font-family:var(--font)}
#vignette{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 50%,transparent 45%,rgba(0,0,0,.42) 100%);opacity:.9}
#damage-flash{
  position:absolute;inset:0;opacity:0;transition:opacity .35s ease;
  background:radial-gradient(ellipse at 50% 50%,transparent 30%,rgba(160,10,0,.5) 78%,rgba(120,0,0,.85) 100%);
}

/* crosshair */
#crosshair{position:absolute;left:50%;top:50%;width:0;height:0;--spread:10px;--ch:rgba(255,255,255,.92)}
#crosshair .ch{position:absolute;background:var(--ch);box-shadow:0 0 3px rgba(0,0,0,.85);transition:transform .06s linear}
#crosshair .ch.t,#crosshair .ch.b{width:2px;height:7px;left:-1px}
#crosshair .ch.l,#crosshair .ch.r{height:2px;width:7px;top:-1px}
#crosshair .ch.t{transform:translateY(calc(var(--spread) * -1))}
#crosshair .ch.b{transform:translateY(var(--spread))}
#crosshair .ch.l{transform:translateX(calc(var(--spread) * -1))}
#crosshair .ch.r{transform:translateX(var(--spread))}
.ch-dot{position:absolute;width:3px;height:3px;left:-1.5px;top:-1.5px;border-radius:50%;background:rgba(255,106,26,.95);box-shadow:0 0 5px rgba(255,106,26,.7)}

#hitmarker{position:absolute;left:50%;top:50%;width:0;height:0;opacity:0}
#hitmarker span{position:absolute;width:2px;height:11px;background:#fff;left:-1px;top:-5.5px;box-shadow:0 0 4px rgba(0,0,0,.9)}
#hitmarker span:nth-child(1){transform:rotate(45deg) translateY(-12px)}
#hitmarker span:nth-child(2){transform:rotate(135deg) translateY(-12px)}
#hitmarker span:nth-child(3){transform:rotate(225deg) translateY(-12px)}
#hitmarker span:nth-child(4){transform:rotate(315deg) translateY(-12px)}
#hitmarker.head span{background:var(--accent-2)}
#hitmarker.show{animation:hm .24s ease-out}
@keyframes hm{0%{opacity:1;transform:scale(.75)}100%{opacity:0;transform:scale(1.25)}}

/* top left mission */
#top-left{position:absolute;left:max(18px,env(safe-area-inset-left));top:max(16px,env(safe-area-inset-top));width:min(340px,42vw)}
.eyebrow{font-size:11px;letter-spacing:.34em;color:var(--accent);font-weight:700}
#mission-name{font-size:27px;line-height:1;letter-spacing:.06em;font-weight:700;margin:6px 0 9px;text-shadow:0 2px 12px rgba(0,0,0,.8)}
#objective-row{display:flex;justify-content:space-between;align-items:baseline;font-size:10.5px;letter-spacing:.16em;color:#c3cfd2}
#objective-row b{font-family:var(--mono);font-size:12px;color:#fff;letter-spacing:.05em}
.mini-bar{height:3px;background:rgba(255,255,255,.14);margin-top:7px;overflow:hidden}
.mini-bar i{display:block;height:100%;width:0%;background:linear-gradient(90deg,var(--accent),var(--accent-2));transition:width .25s}
#status-row{display:flex;gap:14px;margin-top:6px;font-family:var(--mono);font-size:9px;letter-spacing:.12em;color:#8d9ca0}
#combo-text{color:var(--accent-2)}

/* radar */
#top-right{position:absolute;right:max(18px,env(safe-area-inset-right));top:max(16px,env(safe-area-inset-top));display:flex;flex-direction:column;align-items:flex-end;gap:8px}
#radar-wrap{position:relative;width:112px;height:112px}
#radar{width:112px;height:112px;display:block;border-radius:50%;background:rgba(4,8,9,.62);border:1px solid rgba(255,255,255,.14);box-shadow:inset 0 0 22px rgba(0,0,0,.55),0 4px 18px rgba(0,0,0,.35)}
.radar-ring{position:absolute;inset:23px;border:1px solid rgba(255,255,255,.08);border-radius:50%}
.radar-n{position:absolute;top:2px;left:50%;transform:translateX(-50%);font-size:8px;letter-spacing:.2em;color:#8b9a9e}
#score{font-family:var(--mono);font-size:9.5px;letter-spacing:.13em;color:#93a2a5;background:rgba(6,10,11,.55);padding:4px 8px;border:1px solid rgba(255,255,255,.09)}
#score b{color:#fff;font-size:11px;letter-spacing:.03em;margin-left:4px}

/* feed */
#feed{position:absolute;left:50%;top:16%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:4px;width:min(520px,80vw)}
.feed-line{font-size:11px;letter-spacing:.2em;color:#d7e1e3;background:rgba(5,9,10,.55);padding:4px 10px;border-left:2px solid var(--accent);animation:feedIn .2s ease-out;text-transform:uppercase}
.feed-line.head{border-left-color:var(--accent-2);color:var(--accent-2)}
.feed-line.out{opacity:0;transition:opacity .5s}
@keyframes feedIn{from{opacity:0;transform:translateY(-5px)}to{opacity:1}}

/* banner */
#banner{position:absolute;left:50%;top:33%;transform:translate(-50%,-50%);text-align:center;width:min(720px,92vw);animation:bannerIn .5s ease-out}
#banner:before{content:"";position:absolute;left:50%;top:-18px;bottom:-18px;width:min(720px,92vw);transform:translateX(-50%);background:linear-gradient(90deg,transparent,rgba(4,8,9,.68) 20%,rgba(4,8,9,.68) 80%,transparent)}
#banner>*{position:relative}
.banner-kicker{font-size:11px;letter-spacing:.5em;color:var(--accent);font-weight:700}
#banner-title{font-size:clamp(36px,6vw,64px);line-height:.95;letter-spacing:.04em;margin:8px 0 10px;text-shadow:0 8px 30px rgba(0,0,0,.7)}
#banner-sub{font-size:11px;letter-spacing:.3em;color:#c4d0d3}
@keyframes bannerIn{from{opacity:0;transform:translate(-50%,-50%) scale(.97)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}

/* toast */
#toast{position:absolute;left:50%;bottom:24%;transform:translateX(-50%);font-size:11px;letter-spacing:.28em;color:var(--accent-2);background:rgba(4,8,9,.7);padding:7px 14px;border:1px solid rgba(255,176,58,.28);text-transform:uppercase;transition:opacity .3s,transform .3s}
#toast.show{opacity:1}
#toast.hide{opacity:0;transform:translate(-50%,6px)}

/* health */
#health-panel{position:absolute;left:max(18px,env(safe-area-inset-left));bottom:max(20px,env(safe-area-inset-bottom));width:min(270px,38vw)}
.hp-head{display:flex;justify-content:space-between;align-items:baseline;font-size:10px;letter-spacing:.24em;color:#a9b6b9}
.hp-head b{font-family:var(--mono);font-size:24px;letter-spacing:-.02em;color:#fff;line-height:1}
#health-bar{height:7px;background:rgba(10,15,16,.75);border:1px solid rgba(255,255,255,.14);margin-top:5px;padding:1px}
#health-fill{display:block;height:100%;width:100%;background:linear-gradient(90deg,#69e07a,#b7ff8a);transition:width .22s,background .3s;box-shadow:0 0 10px rgba(105,224,122,.35)}
#health-fill.warn{background:linear-gradient(90deg,#ffb03a,#ffd36e);box-shadow:0 0 10px rgba(255,176,58,.35)}
#health-fill.crit{background:linear-gradient(90deg,#ff3b2f,#ff7d57);box-shadow:0 0 12px rgba(255,59,47,.5);animation:pulse 1s infinite}
@keyframes pulse{50%{opacity:.55}}
#health-sub{display:flex;justify-content:space-between;margin-top:5px;font-family:var(--mono);font-size:9px;letter-spacing:.12em;color:#7f8f93}

/* weapon */
#weapon-panel{position:absolute;right:max(18px,env(safe-area-inset-right));bottom:max(20px,env(safe-area-inset-bottom));text-align:right;min-width:230px}
#weapon-slots{display:flex;gap:4px;justify-content:flex-end;margin-bottom:8px}
.wslot{width:29px;height:25px;border:1px solid rgba(255,255,255,.14);background:rgba(5,10,11,.55);display:flex;align-items:center;justify-content:center;font-family:var(--mono);font-size:9px;color:#7e8e92;position:relative;transition:.15s}
.wslot.active{border-color:var(--accent);color:#fff;background:rgba(255,106,26,.14)}
.wslot.empty{opacity:.35}
.wslot small{font-size:7px;position:absolute;bottom:1px;right:2px;color:#637174}
#weapon-name{font-size:12px;letter-spacing:.24em;color:#ccd7da}
#weapon-main{display:flex;align-items:flex-end;justify-content:flex-end;gap:10px;margin-top:2px}
.ammo{display:flex;align-items:baseline;gap:4px;font-family:var(--mono)}
#ammo-mag{font-size:42px;line-height:.85;color:#fff;letter-spacing:-.03em}
#ammo-reserve{font-size:11px;color:#8b9a9e}
#ammo-mag.low{color:var(--red)}
#reload-hint{margin-top:7px;font-size:9px;letter-spacing:.24em;color:var(--accent-2);display:flex;align-items:center;justify-content:flex-end;gap:8px}
#reload-bar-wrap{width:70px;height:3px;background:rgba(255,255,255,.16);display:block}
#reload-bar{display:block;height:100%;width:0;background:var(--accent-2)}

#controls-hint{position:absolute;left:50%;bottom:max(14px,env(safe-area-inset-bottom));transform:translateX(-50%);font-family:var(--mono);font-size:8px;letter-spacing:.16em;color:rgba(170,186,189,.45);white-space:nowrap}

/* scope */
#scope{position:absolute;inset:0;background:radial-gradient(circle at 50% 50%,transparent 0,transparent 31vh,rgba(0,0,0,.97) 32vh);display:flex;align-items:center;justify-content:center}
.scope-vignette{position:absolute;inset:0;background:radial-gradient(circle at 50% 50%,transparent 26vh,rgba(0,0,0,.75) 32vh)}
.scope-ring{width:62vh;height:62vh;border-radius:50%;border:1px solid rgba(0,0,0,.9);box-shadow:inset 0 0 60px rgba(0,0,0,.6),0 0 0 1px rgba(255,255,255,.06)}
.scope-lines{position:absolute;width:62vh;height:62vh;border-radius:50%}
.scope-lines i{position:absolute;background:rgba(10,10,10,.9)}
.scope-lines i:nth-child(1){left:50%;top:6%;width:1px;height:22%;transform:translateX(-50%)}
.scope-lines i:nth-child(2){left:50%;bottom:6%;width:1px;height:22%;transform:translateX(-50%)}
.scope-lines i:nth-child(3){top:50%;left:6%;height:1px;width:22%;transform:translateY(-50%)}
.scope-lines i:nth-child(4){top:50%;right:6%;height:1px;width:22%;transform:translateY(-50%)}
.scope-dot{position:absolute;left:50%;top:50%;width:4px;height:4px;margin:-2px;border-radius:50%;background:var(--red);box-shadow:0 0 6px rgba(255,77,61,.7)}
.scope-label{position:absolute;bottom:12vh;left:50%;transform:translateX(-50%);font-family:var(--mono);font-size:9px;letter-spacing:.24em;color:rgba(255,255,255,.5)}

/* ---------- overlays / menus ---------- */
.overlay{position:fixed;inset:0;z-index:60;display:flex;align-items:center;justify-content:center;padding:clamp(14px,3vw,44px);overflow-y:auto;overscroll-behavior:contain}
#menu{background:linear-gradient(100deg,rgba(4,7,8,.96) 0%,rgba(4,7,8,.86) 48%,rgba(4,7,8,.52) 100%)}
.menu-shade{position:absolute;inset:0;pointer-events:none;background:
  repeating-linear-gradient(0deg,rgba(255,255,255,.018) 0 1px,transparent 1px 3px),
  radial-gradient(ellipse at 78% 35%,rgba(255,106,26,.13),transparent 55%),
  linear-gradient(0deg,rgba(0,0,0,.7),transparent 45%)}
.menu-inner{position:relative;width:min(1080px,100%);margin:auto;padding:12px 0}
.brand{position:relative;margin-bottom:clamp(16px,3vh,34px)}
.brand-tag{display:flex;align-items:center;gap:9px;font-size:10px;letter-spacing:.34em;color:#a8b6b9}
.brand-tag .dot{width:6px;height:6px;background:var(--accent);border-radius:50%;box-shadow:0 0 10px var(--accent);animation:blink 2.4s infinite}
@keyframes blink{50%{opacity:.35}}
.brand h1{font-size:clamp(54px,10vw,108px);line-height:.8;letter-spacing:.015em;font-weight:700;margin:12px 0 10px;text-shadow:0 12px 50px rgba(0,0,0,.7)}
.brand h1 span{color:var(--accent);margin-left:.12em;text-shadow:0 0 46px rgba(255,106,26,.35)}
.brand-sub{font-size:clamp(11px,1.4vw,14px);letter-spacing:.26em;color:#bcc9cc;text-transform:uppercase}
.menu-grid{display:grid;grid-template-columns:1.08fr .92fr;gap:14px;align-items:start}
.menu-card{background:linear-gradient(160deg,rgba(14,20,21,.88),rgba(8,12,13,.8));border:1px solid var(--line);padding:clamp(14px,2vw,24px);backdrop-filter:blur(7px);position:relative}
.menu-card:before{content:"";position:absolute;top:-1px;left:-1px;width:34px;height:2px;background:var(--accent)}
.menu-card header{display:flex;align-items:center;gap:9px;font-size:11px;letter-spacing:.3em;color:#dbe5e7;margin-bottom:13px}
.menu-card header span{font-family:var(--mono);color:var(--accent);font-size:9px}
.brief{font-size:12.5px;line-height:1.55;letter-spacing:.05em;color:#9dadaf;margin-bottom:15px;max-width:56ch}
.section-label{font-size:9px;letter-spacing:.3em;color:#6f7f83;margin:14px 0 8px}
#level-chips{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}
.lchip{height:34px;border:1px solid rgba(255,255,255,.12);background:rgba(255,255,255,.03);color:#9dadaf;font-family:var(--mono);font-size:10px;cursor:pointer;transition:.15s;position:relative}
.lchip:hover:not(.locked){border-color:rgba(255,106,26,.55);color:#fff;background:rgba(255,106,26,.1)}
.lchip.active{border-color:var(--accent);color:#fff;background:rgba(255,106,26,.22);box-shadow:0 0 18px rgba(255,106,26,.15)}
.lchip.locked{opacity:.3;cursor:not-allowed}
.lchip.locked:after{content:"✕";position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:8px;color:#8a999c}
.lchip span{display:block;font-family:var(--font);font-size:7px;letter-spacing:.12em;margin-top:1px;color:#7c8b8e}
.menu-actions{display:flex;gap:8px;margin-top:18px;flex-wrap:wrap}
.btn{border:1px solid transparent;background:transparent;color:var(--text);font-family:var(--font);font-size:12px;letter-spacing:.22em;padding:13px 20px;cursor:pointer;transition:.16s;text-transform:uppercase;font-weight:600}
.btn.primary{background:var(--accent);color:#140a04;box-shadow:0 8px 26px rgba(255,106,26,.22);flex:1;min-width:160px}
.btn.primary:hover{background:var(--accent-2);transform:translateY(-1px)}
.btn.ghost{border-color:var(--line-strong);color:#c2cfd1}
.btn.ghost:hover{border-color:#fff;background:rgba(255,255,255,.06)}
.btn:disabled{opacity:.4;cursor:not-allowed;transform:none}
.save-line{margin-top:10px;font-family:var(--mono);font-size:8.5px;letter-spacing:.14em;color:#6b7a7e;text-transform:uppercase}

/* arsenal */
#menu-weapons{display:flex;flex-direction:column;gap:6px}
.mw{display:grid;grid-template-columns:26px 1fr auto;gap:10px;align-items:center;padding:7px 8px;border:1px solid rgba(255,255,255,.07);background:rgba(255,255,255,.02)}
.mw .n{font-family:var(--mono);font-size:9px;color:var(--accent);border:1px solid rgba(255,106,26,.3);width:22px;height:22px;display:flex;align-items:center;justify-content:center}
.mw .nm{font-size:12px;letter-spacing:.13em;color:#dde7e9}
.mw .ds{font-size:8px;letter-spacing:.1em;color:#7f8f93;margin-top:1px}
.mw .st{font-family:var(--mono);font-size:8px;letter-spacing:.06em;color:#93a3a7;text-align:right;line-height:1.5}
.mw .st b{color:#fff;font-weight:400}
.key-grid{display:grid;grid-template-columns:1fr 1fr;gap:5px 10px}
.key-grid>div{display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:.15em;color:#8f9fa2}
kbd{font-family:var(--mono);font-size:8px;letter-spacing:.04em;color:#cfdbdd;border:1px solid rgba(255,255,255,.17);background:rgba(255,255,255,.05);padding:3px 5px;min-width:34px;text-align:center}
.mobile-note{display:none;margin-top:11px;font-size:9.5px;line-height:1.5;letter-spacing:.07em;color:#7f9093;border-left:2px solid rgba(255,106,26,.4);padding-left:9px}
.menu-foot{display:flex;justify-content:space-between;align-items:center;margin-top:14px;font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:#5d6b6f}
.icon-btn{background:none;border:1px solid rgba(255,255,255,.12);color:#85959a;font-family:var(--mono);font-size:8px;letter-spacing:.14em;padding:6px 9px;cursor:pointer}
.icon-btn:hover{color:#fff;border-color:#fff}
.icon-btn.off{color:#6b787c;text-decoration:line-through}

/* dialogs */
#pause,#complete,#gameover,#victory{background:rgba(3,6,7,.82);backdrop-filter:blur(8px)}
.dialog{position:relative;width:min(520px,100%);background:linear-gradient(165deg,#101718,#080c0d);border:1px solid var(--line-strong);padding:clamp(22px,4vw,40px);box-shadow:0 40px 120px rgba(0,0,0,.7)}
.dialog:before{content:"";position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),transparent 60%)}
.dialog-kicker{font-size:10px;letter-spacing:.42em;color:var(--accent);font-weight:700}
.dialog-kicker.success{color:var(--green)}
.dialog h2{font-size:clamp(28px,4.4vw,42px);line-height:1;letter-spacing:.03em;margin:8px 0 20px;text-transform:uppercase}
.dialog-copy{font-size:12px;line-height:1.6;color:#9eadaf;letter-spacing:.06em;max-width:44ch}
.dialog-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(255,255,255,.09);margin:8px 0 18px}
.dialog-stats>div{background:#0b1213;padding:11px 12px}
.dialog-stats span{display:block;font-size:8px;letter-spacing:.2em;color:#758589;margin-bottom:5px}
.dialog-stats b{font-family:var(--mono);font-size:20px;font-weight:400;color:#fff}
#complete .dialog-stats{grid-template-columns:repeat(4,1fr)}
#victory .dialog-stats{grid-template-columns:repeat(3,1fr)}
.reward{font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:var(--accent-2);border:1px dashed rgba(255,176,58,.25);padding:8px 10px;margin-bottom:18px}
.dialog-actions{display:flex;gap:8px;flex-wrap:wrap}
.dialog-actions .btn{flex:1;min-width:130px}
.slider-row{display:flex;align-items:center;gap:10px;font-size:9px;letter-spacing:.18em;color:#93a3a6;margin:2px 0 18px}
.slider-row input{flex:1;accent-color:var(--accent);height:3px}
.slider-row b{font-family:var(--mono);color:#fff;font-size:11px;width:28px;text-align:right}
.dialog.danger:before{background:linear-gradient(90deg,var(--red),transparent 60%)}
.dialog.danger .dialog-kicker{color:var(--red)}
.dialog.victory:before{background:linear-gradient(90deg,var(--green),transparent 60%)}

/* ---------- touch ---------- */
#touch{display:none;position:absolute;inset:0;pointer-events:none}
#look-zone{position:absolute;right:0;top:0;width:58%;height:100%;pointer-events:auto;touch-action:none}
#stick{position:absolute;left:max(22px,env(safe-area-inset-left));bottom:max(26px,env(safe-area-inset-bottom));width:118px;height:118px;border-radius:50%;border:1px solid rgba(255,255,255,.18);background:rgba(5,10,11,.32);pointer-events:auto;touch-action:none;box-shadow:inset 0 0 24px rgba(0,0,0,.35)}
#stick:after{content:"";position:absolute;inset:32px;border:1px dashed rgba(255,255,255,.12);border-radius:50%}
#stick-knob{position:absolute;left:50%;top:50%;width:46px;height:46px;margin:-23px 0 0 -23px;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.3),rgba(255,255,255,.08));border:1px solid rgba(255,255,255,.4);transition:transform .04s linear}
#touch-buttons{position:absolute;right:max(18px,env(safe-area-inset-right));bottom:max(22px,env(safe-area-inset-bottom));display:grid;grid-template-columns:repeat(3,54px);grid-template-rows:54px 54px 76px;gap:8px;pointer-events:none}
.tbtn{pointer-events:auto;touch-action:none;border-radius:50%;border:1px solid rgba(255,255,255,.26);background:rgba(8,13,14,.5);color:#e8f0f2;font-family:var(--font);font-size:8.5px;letter-spacing:.12em;backdrop-filter:blur(3px);cursor:pointer;padding:0}
.tbtn:active,.tbtn.on{background:rgba(255,106,26,.35);border-color:var(--accent)}
.tbtn.fire{grid-column:1 / span 2;grid-row:3;width:auto;height:auto;border-radius:52px;background:rgba(255,106,26,.2);border-color:rgba(255,106,26,.6);font-size:12px;letter-spacing:.2em;color:#ffd9c2}
.tbtn.fire:active{background:rgba(255,106,26,.6)}
#btn-aim{grid-column:1;grid-row:2}
#btn-reload{grid-column:2;grid-row:2}
#btn-swap{grid-column:3;grid-row:2}
#btn-jump{grid-column:3;grid-row:1}

#rotate-hint{position:fixed;left:50%;bottom:20px;transform:translateX(-50%);z-index:80;font-size:10px;letter-spacing:.2em;color:#c6d2d4;background:rgba(4,8,9,.8);padding:8px 12px;border:1px solid rgba(255,255,255,.14)}

/* ---------- responsive ---------- */
@media (max-width:900px){
  .menu-grid{grid-template-columns:1fr}
  .menu-card .key-grid{grid-template-columns:1fr 1fr}
  #menu .menu-inner{padding-bottom:24px}
  .brand h1{font-size:clamp(52px,14vw,84px)}
}
@media (hover:none) and (pointer:coarse){
  #touch:not(.hidden){display:block}
  #controls-hint{display:none}
  .mobile-note{display:block}
  #weapon-panel{right:auto;left:50%;transform:translateX(-50%);bottom:max(10px,env(safe-area-inset-bottom));text-align:center;min-width:0;width:auto}
  #weapon-slots{justify-content:center}
  #weapon-main{justify-content:center}
  #ammo-mag{font-size:26px}
  #weapon-name{font-size:9px}
  #reload-hint{justify-content:center}
  #health-panel{width:132px;bottom:auto;top:calc(max(16px,env(safe-area-inset-top)) + 108px)}
  .hp-head b{font-size:17px}
  .hp-head span{font-size:8px}
  #health-sub{font-size:7px}
  #top-left{width:44vw}
  #mission-name{font-size:16px;margin:4px 0 6px}
  .eyebrow{font-size:8px}
  #objective-row{font-size:8px}
  #objective-row b{font-size:9px}
  #radar-wrap,#radar{width:84px;height:84px}
  #top-right{gap:5px}
  #score{font-size:7.5px;padding:3px 5px}
  #score b{font-size:9px}
  #feed{top:20%}
  .feed-line{font-size:8px;padding:3px 7px}
  #banner-title{font-size:34px}
  #banner-sub{font-size:9px;letter-spacing:.18em}
  .scope-ring,.scope-lines{width:78vmin;height:78vmin}
  #scope{background:radial-gradient(circle at 50% 50%,transparent 0,transparent 39vmin,rgba(0,0,0,.97) 40vmin)}
  .scope-vignette{background:radial-gradient(circle at 50% 50%,transparent 33vmin,rgba(0,0,0,.75) 40vmin)}
  .dialog{padding:24px 18px}
  .dialog-stats b{font-size:16px}
  .dialog-stats span{font-size:7px}
}
@media (max-height:560px){
  .brand h1{font-size:50px}
  .brand{margin-bottom:10px}
  .menu-card{padding:12px}
  .brief{display:none}
  .brand-tag{font-size:8px}
  .brand-sub{font-size:9px}
  .menu-foot{margin-top:6px}
}
@media (max-width:560px){
  #top-left{width:52vw}
  #mission-name{font-size:18px}
  .brand h1{letter-spacing:0}
  #complete .dialog-stats{grid-template-columns:repeat(2,1fr)}
  .menu-actions .btn{width:100%}
  #level-chips{gap:3px}
  .lchip{height:30px}
  #stick{width:104px;height:104px}
  #stick-knob{width:42px;height:42px;margin:-21px 0 0 -21px}
  #touch-buttons{grid-template-columns:repeat(3,46px);grid-template-rows:46px 46px 66px;gap:6px}
  #health-panel{width:120px;top:calc(max(14px,env(safe-area-inset-top)) + 96px)}
  #objective-text{font-size:7px;letter-spacing:.05em}
}

