  let muzzleZ = -0.5;
  let holdPos = new THREE.Vector3(0.31, -0.29, -0.55);

  if (id === 'pistol') {
    box(root, gunmetal, 0.072, 0.082, 0.33, 0, 0.03, -0.12);
    box(root, dark, 0.066, 0.046, 0.28, 0, -0.032, -0.1);
